/**
 * ToolCall's states fixture in element form, with the React fixture's entry
 * names, so a contract's `when <state>` names the same entry in every shell. Each
 * entry is the markup a page writes, and what its script sets once the elements
 * are defined.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tool-call.ts`. Never edit it by hand.
 */
import type { ComponentStates } from '@polymorph/elements'

import '../structure/CodeBlock'
import './ToolCall'

export const states: ComponentStates = {
  component: 'ToolCall',
  entries: [
    {
      name: 'running — the glyph spins, the row is busy',
      html: `<poly-tool-call name="read_file" summary="src/webhooks/retry.ts" status="running" input='{"path":"src/webhooks/retry.ts","range":{"start":1,"end":80}}'></poly-tool-call>`,
      subject: 'poly-tool-call',
      expect: { 'data-status': 'running', 'aria-busy': 'true' },
    },
    {
      name: 'done — closed, with a duration',
      html: `<poly-tool-call name="read_file" summary="src/webhooks/retry.ts" status="done" duration="0.4s" input='{"path":"src/webhooks/retry.ts","range":{"start":1,"end":80}}'>
  <poly-code-block slot="output">export const RETRY_CAP = 5
export const FIRST_RETRY_MS = 2_000</poly-code-block>
</poly-tool-call>`,
      subject: 'poly-tool-call',
      expect: { 'data-status': 'done', 'data-state': 'closed' },
    },
    {
      name: 'done, open — the input as JsonTree, the output as the app composed it',
      html: `<poly-tool-call name="read_file" summary="src/webhooks/retry.ts" status="done" duration="0.4s" input='{"path":"src/webhooks/retry.ts","range":{"start":1,"end":80}}' default-open>
  <poly-code-block slot="output">export const RETRY_CAP = 5
export const FIRST_RETRY_MS = 2_000</poly-code-block>
</poly-tool-call>`,
      subject: 'poly-tool-call',
      expect: { 'data-state': 'open' },
    },
    {
      name: 'a string input — CodeBlock, a shell command',
      html: `<poly-tool-call name="run_command" icon="terminal" summary="pnpm test --project ui" status="done" duration="41s" default-open></poly-tool-call>`,
      subject: 'poly-tool-call',
      setup: (find) => {
        const e0 = find('poly-tool-call', 0)
        e0.input = 'pnpm test --project ui'
      },
    },
    {
      name: 'pending — queued behind the one before it',
      html: `<poly-tool-call name="search_web" icon="network" summary="webhook idempotency" status="pending"></poly-tool-call>`,
      subject: 'poly-tool-call',
      expect: { 'data-status': 'pending' },
    },
    {
      name: 'awaiting approval — the ApprovalCard beside it asks',
      html: `<poly-tool-call name="run_command" icon="terminal" summary="pnpm db:migrate --env staging" status="approval"></poly-tool-call>`,
      subject: 'poly-tool-call',
      expect: { 'data-status': 'approval' },
    },
    {
      name: 'failed — the app’s words, open',
      html: `<poly-tool-call name="search_web" icon="network" summary="webhook idempotency" status="error" message="The search provider returned 429. Retrying is up to you." default-open></poly-tool-call>`,
      subject: 'poly-tool-call',
      expect: { 'data-status': 'error' },
    },
    {
      name: 'denied',
      html: `<poly-tool-call name="run_command" icon="terminal" summary="rm -rf dist" status="denied" message="Denied by you."></poly-tool-call>`,
      subject: 'poly-tool-call',
      expect: { 'data-status': 'denied' },
    },
    {
      name: 'nothing inside — a row, not a button',
      html: `<poly-tool-call name="list_tools" status="done" duration="0.1s"></poly-tool-call>`,
      subject: 'poly-tool-call',
    },
  ],
}
